<div class="sl-head"><div><h1 class="sl-title">Delivery job</h1><p class="sl-lede">Confirm the destination, parcel list and handover.</p></div><a class="sl-btn ghost" href="driver_app.php">My jobs</a></div>
<?php if(!$d['ready']||!$d['request']): ?><div class="sl-card sl-empty">This delivery is not assigned to you or is unavailable.</div><?php return;endif;$r=$d['request'];include __DIR__.'/partials/delivery_summary.php'; ?>
<?php if($r->state==='assigned'): ?><button class="sl-btn block" data-sl-action="ajax/sl/delivery_ajax.php" data-p-op="start" data-p-id="<?= (int)$r->id ?>" data-sl-confirm="Confirm all parcels are with you and start delivery?" data-sl-reload>Start delivery with these parcels</button><?php endif; ?>
<?php if(in_array($r->state,['assigned','onroute'],true)): ?><a class="sl-btn ghost block" href="tel:<?= h(preg_replace('/[^+0-9]/','',$r->contact_phone)) ?>">Call <?= h($r->contact_name) ?></a><?php endif; ?>
<?php if($r->state==='onroute'): ?>
<form class="sl-card col g16" data-sl-form data-sl-redirect method="post" action="ajax/sl/delivery_ajax.php" enctype="multipart/form-data"><h2 class="sl-ct">Confirm handover</h2><input type="hidden" name="op" value="deliver"><input type="hidden" name="id" value="<?= (int)$r->id ?>"><label class="sl-field"><span class="sl-lab">Customer pickup codes (comma-separated if several)</span><input class="sl-in mono" name="code" required pattern="[0-9]{6}( *, *[0-9]{6})*" maxlength="350" autocomplete="off"></label><label class="sl-field"><span class="sl-lab">Receiver’s full name</span><input class="sl-in" name="receiver" required maxlength="150"></label><label class="sl-field"><span class="sl-lab">Photo of the handover</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment" required></label><label class="row g8"><input type="checkbox" name="fee_collected" value="1">Delivery fee <?= h(dl_money((int)$r->amount_cents,$r->currency)) ?> collected</label><p class="sm mut">This records collection of the delivery fee only. It does not settle the shipping invoice.</p><button class="sl-btn block sl-mobile-sticky" type="submit">Confirm delivery of all <?= count(json_decode($r->parcel_json,true)) ?> parcels</button></form>
<form class="sl-card col g12" data-sl-form data-sl-redirect action="ajax/sl/delivery_ajax.php" method="post"><h2 class="sl-ct">Unable to deliver?</h2><input type="hidden" name="op" value="fail"><input type="hidden" name="id" value="<?= (int)$r->id ?>"><label class="sl-field"><span class="sl-lab">Reason for the failed attempt</span><textarea class="sl-in" name="note" required minlength="3" maxlength="500"></textarea></label><button class="sl-btn ghost" type="submit">Report failed attempt</button></form>
<?php elseif($r->state==='failed'): ?><div class="sl-banner warn">Dispatch must review and reassign this delivery before another attempt.</div><?php endif; ?>
